def verifier(assign):
    # Validate presence of required fields
    required = ['primes_str', 'max_exponents_str', 'a_coeffs_str', 'b_coeffs_str', 'cycle_length']
    for key in required:
        if key not in assign:
            # Missing required parameter
            return (False, None)
    # Parse helper: accepts comma/space separated integers
    def parse_int_list(s):
        if not isinstance(s, str):
            return None
        s = s.replace(';', ',').replace('|', ',')
        parts = []
        for chunk in s.split(','):
            chunk = chunk.strip()
            if chunk == '':
                continue
            for sub in chunk.split():
                if sub.strip() != '':
                    try:
                        parts.append(int(sub))
                    except Exception:
                        return None
        return parts
    primes = parse_int_list(assign['primes_str'])
    n_list = parse_int_list(assign['max_exponents_str'])
    a_list = parse_int_list(assign['a_coeffs_str'])
    b_list = parse_int_list(assign['b_coeffs_str'])
    m = assign['cycle_length']
    # Basic domain checks
    if primes is None or n_list is None or a_list is None or b_list is None:
        return (False, None)
    k = len(primes)
    if not (k == len(n_list) == len(a_list) == len(b_list)):
        return (False, None)
    if k < 3 or k > 6:
        return (False, None)
    # Factor cycle_length and ensure it's product of two distinct odd primes
    def factor_distinct_primes(n):
        fac = {}
        x = n
        d = 2
        while d * d <= x:
            cnt = 0
            while x % d == 0:
                x //= d
                cnt += 1
            if cnt:
                fac[d] = cnt
            d += 1 if d == 2 else 2  # skip even numbers after 2
        if x > 1:
            fac[x] = fac.get(x, 0) + 1
        return fac
    fac = factor_distinct_primes(m)
    if len(fac) != 2:
        return (False, None)
    # All exponents must be 1 and primes odd
    primes_m = list(fac.keys())
    if any(fac[p] != 1 for p in primes_m):
        return (False, None)
    if any(p % 2 == 0 for p in primes_m):
        return (False, None)
    p, q = primes_m[0], primes_m[1]
    # Compute H_i(x) values and counts
    def H_vals(n, a, b):
        vals = []
        for x in range(n+1):
            s_t = (n * (n + 1) - (x - 1) * x) // 2
            h = a * s_t + b * (n - x + 1)
            vals.append(h)
        return vals
    z_p = []
    z_q = []
    z_pq = []
    total = 1
    for i in range(k):
        n = n_list[i]
        a = a_list[i]
        b = b_list[i]
        if n < 0 or a <= 0 or b <= 0:
            return (False, None)
        Hs = H_vals(n, a, b)
        c_p = sum(1 for h in Hs if h % p == 0)
        c_q = sum(1 for h in Hs if h % q == 0)
        c_pq = sum(1 for h in Hs if (h % p == 0 and h % q == 0))
        z_p.append(c_p)
        z_q.append(c_q)
        z_pq.append(c_pq)
        total *= (n + 1)
    # Inclusion-exclusion
    A = 1
    B = 1
    AB = 1
    for i in range(k):
        size_i = n_list[i] + 1
        A *= (size_i - z_p[i])
        B *= (size_i - z_q[i])
        AB *= (size_i - z_p[i] - z_q[i] + z_pq[i])
    answer = total - A - B + AB
    # Difficulty constraints: ensure nontrivial instance
    if total < 1:
        return (False, None)
    if not (0 < answer < total):
        return (False, None)
    if sum(z_p) == 0 or sum(z_q) == 0:
        return (False, None)
    if A <= 0 or B <= 0:
        return (False, None)
    return (True, answer)
